const sidebarEventManager = {
    currentPage: 'profile',
    callbacks: [],
    isExpanded: false,
    lastClickedMenuItem: null,
    isProcessing: false,

    init: function() {
        const menuItems = document.querySelectorAll('.sidebar-nav .nav-item[data-page]');

        menuItems.forEach(item => {
            item.addEventListener('click', (e) => {
                this.handleMenuItemClick(e, item);
            });
        });
        
        this.switchPage(this.currentPage);
        
        const defaultItem = document.querySelector(`.nav-item[data-page="${this.currentPage}"]`);
        if (defaultItem) {
            defaultItem.classList.add('active');
        }
        
        this.setupOutsideClickHandler();
    },
    
    handleMenuItemClick: function(e, item) {
        e.preventDefault();
        e.stopImmediatePropagation();
        
        if (this.isProcessing) {
            return;
        }
        
        if(!开发者UID){return;}
        
        this.isProcessing = true;
        
        try {
            const pageId = item.getAttribute('data-page');
            
            if (this.currentPage !== pageId) {
                this.currentPage = pageId;
                
                document.querySelectorAll('.sidebar-nav .nav-item').forEach(navItem => {
                    navItem.classList.remove('active');
                });
                
                item.classList.add('active');
                
                this.switchPage(pageId);
                this.notifyListeners(pageId);
            }
        } finally {
            setTimeout(() => {
                this.isProcessing = false;
            }, 10);
        }
    },
    
    switchPage: function(pageId) {
        // [scroll-fix] 切页回顶：不继承上一页滚动位置
        try {
            window.scrollTo(0, 0);
            if (document.scrollingElement) document.scrollingElement.scrollTop = 0;
            document.querySelectorAll('.page').forEach(p => { p.scrollTop = 0; });
        } catch (e) {}
        document.querySelectorAll('.page').forEach(page => {
            page.classList.remove('active');
            page.style.display = 'none';
        });
        
        const targetPage = document.getElementById(pageId);
        if (targetPage) {
            targetPage.classList.add('active');
            targetPage.style.display = 'block';
        }
    },
    
    setupOutsideClickHandler: function() {
        document.removeEventListener('click', this.handleOutsideClick);
        this.handleOutsideClick = (e) => {
            const isSidebarClick = e.target.closest('.sidebar-nav');
            
            if (!isSidebarClick) {
                document.querySelectorAll('.sidebar-nav .nav-item').forEach(item => {
                    if (!item.classList.contains('active')) {
                        item.style.backgroundColor = '';
                    }
                });
            }
        };
        
        document.addEventListener('click', this.handleOutsideClick);
    },
    
    addListener: function(callback) {
        if (typeof callback === 'function') {
            this.callbacks.push(callback);
        }
    },
    
    notifyListeners: function(pageId) {
        this.callbacks.forEach(callback => {
            try {
                callback(pageId);
            } catch (error) {
            }
        });
    },
    
    getCurrentPage: function() {
        return this.currentPage;
    },

    navigateTo: function(pageId) {
        const item = document.querySelector(`.nav-item[data-page="${pageId}"]`);
        if (item) {
            this.handleMenuItemClick(new Event('click'), item);
        } else {
            this.currentPage = pageId;
            this.switchPage(pageId);
            this.notifyListeners(pageId);
        }
    },

    getSidebarState: function() {
        return {
            currentPage: this.currentPage,
            activeItems: Array.from(document.querySelectorAll('.sidebar-nav .nav-item.active')).map(item => 
                item.getAttribute('data-page')
            ).filter(Boolean)
        };
    }
};

