function initMobileSidebar() {
    const menuToggle = document.getElementById('menuToggle');
    const sidebar = document.querySelector('.sidebar');
    const overlay = document.getElementById('sidebarOverlay');
    
    if (!menuToggle) return;
    
    function openSidebar() {
        if (sidebar) sidebar.classList.add('open');
        if (overlay) overlay.classList.add('open');
        document.body.style.overflow = 'hidden';
    }
    
    function closeSidebar() {
        if (sidebar) sidebar.classList.remove('open');
        if (overlay) overlay.classList.remove('open');
        document.body.style.overflow = '';
    }
    
    menuToggle.addEventListener('click', openSidebar);
    if (overlay) overlay.addEventListener('click', closeSidebar);
    
    // 点击侧边栏内的导航项后自动关闭
    if (sidebar) {
        sidebar.querySelectorAll('.nav-item').forEach(item => {
            item.addEventListener('click', closeSidebar);
        });
    }
}







let 应用选择器_配置序号 = 0;
let 应用选择器_待选应用ID = '';

function 应用选择器_清空配置() {
    当前选中的应用ID = null;
    当前选中的应用对接密钥 = null;
    当前选中的应用名称 = null;
    当前选中的应用加密格式 = null;
    if (typeof 当前选中的应用加密密钥 !== 'undefined') 当前选中的应用加密密钥 = null;
    当前应用的签名类型 = null;
    当前应用的签名密钥 = null;
}

function 应用选择器_重置配置() {
    ++应用选择器_配置序号;
    应用选择器_待选应用ID = '';
    应用选择器_清空配置();
}

async function 刷新选择器() {
    if(!开发者UID) return;
    
    const appSelector = document.getElementById('应用选择下拉');
    if (!appSelector) return;
    
    try {
        const allApps = await 加载所有实例();
        
        if (allApps && allApps.length > 0) {
            const 新的应用列表 = allApps;
            
            const 当前选项Map = new Map();
            for (const option of appSelector.options) {
                if (option.value) {
                    当前选项Map.set(option.value, option);
                }
            }
            
            const 当前目标应用ID = String(应用选择器_待选应用ID || 当前选中的应用ID || '');
            const 当前选中的应用仍然存在 = 当前目标应用ID &&
                新的应用列表.some(app => String(app.app_id) === 当前目标应用ID);
            
            if (当前目标应用ID && !当前选中的应用仍然存在) {
                应用选择器_重置配置();
                appSelector.value = '';
            }
            
            const 需要保留的应用ID = new Set();
            
            新的应用列表.forEach((app, index) => {
                const appId = app.app_id;
                const appName = app.app_name || `应用${index + 1}`;
                
                if (appId) {
                    需要保留的应用ID.add(appId);
                    
                    if (当前选项Map.has(appId)) {
                        const option = 当前选项Map.get(appId);
                        option.textContent = `${appName} (ID: ${appId})`;
                    } else {
                        const option = document.createElement('option');
                        option.value = appId;
                        option.textContent = `${appName} (ID: ${appId})`;
                        appSelector.appendChild(option);
                    }
                }
            });
            
            for (let i = appSelector.options.length - 1; i >= 0; i--) {
                const option = appSelector.options[i];
                if (option.value && !需要保留的应用ID.has(option.value)) {
                    appSelector.removeChild(option);
                    if (option.value === 当前选中的应用ID) {
                        应用选择器_重置配置();
                        appSelector.value = '';
                    }
                }
            }
            
            if (!appSelector.querySelector('option[value=""]')) {
                const defaultOption = document.createElement('option');
                defaultOption.value = "";
                defaultOption.textContent = "请选择应用实例...";
                appSelector.insertBefore(defaultOption, appSelector.firstChild);
            }
            
            if (当前选中的应用ID) {
                appSelector.value = 当前选中的应用ID;
            }
        } else {
            appSelector.innerHTML = '<option value="">请选择应用实例...</option>';
            应用选择器_重置配置();
            当前应用实例列表 = [];
        }
        
    } catch (error) {
        appSelector.innerHTML = '<option value="">请选择应用实例...</option>';
        应用选择器_重置配置();
    }
}
async function 处理应用发生变化(e) {
    if(!开发者UID) return;

    const triggerSelect = (e && e.target) ? e.target : 
                         (e && typeof e === 'object' && e.tagName === 'SELECT' ? e : 
                         document.getElementById('应用选择下拉'));
    
    if (!triggerSelect || triggerSelect.tagName !== 'SELECT') return;
    
    const selectedAppId = triggerSelect.value.trim();
    const 配置序号 = ++应用选择器_配置序号;
    应用选择器_待选应用ID = selectedAppId;
    // 配置就绪前不发布新 ID，现有依赖模块的“未选择应用”守卫仍然生效。
    应用选择器_清空配置();
    document.querySelectorAll('select[id="appSelector"]').forEach(select => {
        if (select !== triggerSelect) {
            try {
                select.value = selectedAppId;
            } catch(err) {
            }
        }
    });
    if (!selectedAppId) return;

    const 仍是当前选择 = () => 配置序号 === 应用选择器_配置序号
        && 应用选择器_待选应用ID === selectedAppId
        && triggerSelect.value.trim() === selectedAppId;
    try {
        const response = await 获取加密方案(selectedAppId);
        if (!仍是当前选择()) return;
        const config = response && response.data;
        if (!config || typeof config !== 'object'
            || typeof config.api_key !== 'string' || typeof config.app_name !== 'string'
            || config.encryption_format == null || config.qm_format == null || typeof config.qm_key !== 'string'
            || (config.app_id != null && String(config.app_id) !== selectedAppId)) {
            alert('应用配置加载失败，请重新选择应用', false);
            return;
        }
        当前选中的应用对接密钥 = config.api_key;
        当前选中的应用名称 = config.app_name;
        当前选中的应用加密格式 = String(config.encryption_format);
        if (typeof 当前选中的应用加密密钥 !== 'undefined') 当前选中的应用加密密钥 = config.api_key;
        当前应用的签名类型 = String(config.qm_format);
        当前应用的签名密钥 = config.qm_key;
        当前选中的应用ID = selectedAppId;
        if (当前界面 == 'users') {
            加载子用户数据(子用户管理_当前页码);
        } else if (当前界面 == 'cards') {
            加载卡密数据(卡密管理_当前页码);
        } else if (当前界面 == 'cloudUpdate') {
            加载云更新数据(云更新管理_当前页码);
        }
    } catch (error) {
        if (仍是当前选择()) alert('应用配置加载失败，请重新选择应用', false);
    }
}


document.addEventListener('DOMContentLoaded', function() {
    sidebarEventManager.init();
    initMobileSidebar();
    sidebarEventManager.addListener(function(pageId) {
        处理界面切换(pageId);
    });
});